code='''from collections import Counter, defaultdict, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            bh, bw = maxr - minr + 1, maxc - minc + 1
            if bh != bw or bh < 3 or bh % 2 == 0:
                continue
            cr, cc = (minr + maxr) // 2, (minc + maxc) // 2
            centers.append((cr, cc, grid[cr][cc]))

    if not centers:
        return [row[:] for row in grid]
    common = Counter(color for r, c, color in centers).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for color in set(v for r, c, v in centers if v != common):
        points = [(r, c) for r, c, v in centers if v == color]
        by_row = defaultdict(list)
